'use strict';
const FINISH_MS=900, KEY='palm92-jarvis-v1', $=id=>document.getElementById(id), escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={notes:[],tasks:[],audit:[],drafts:[]},storageOK=true;
try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&['notes','tasks','audit','drafts'].every(k=>Array.isArray(v[k])))data=v}catch(e){storageOK=false}
let page='Home',voice=false,recognition=null,timer,buffer='';
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));$('storage').textContent='Saved in this browser'}catch(e){storageOK=false;$('storage').textContent='Storage unavailable. Export backup.'} }
function log(action){data.audit.unshift({at:new Date().toISOString(),action});save()}
function speak(text){if(!voice||new URLSearchParams(location.search).get('mute')==='1'||!('speechSynthesis'in window))return;speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=Number($('speed').value)||1.2;u.voice=speechSynthesis.getVoices().find(v=>v.name===$('voiceChoice').value)||speechSynthesis.getVoices().find(v=>v.lang==='en-GB')||null;u.onstart=()=>$('status').textContent='Speaking';u.onend=()=>$('status').textContent='Ready';speechSynthesis.speak(u)}
function answer(text){$('answer').textContent=text;speak(text);$('status').textContent='Ready'}
const sections=['Home','Notes','GRC / TPRM','Work queue','Email','LinkedIn','REA','Preflight','Audit'];
$('nav').innerHTML=sections.map(n=>`<button data-nav="${n}">${n}</button>`).join('');$('nav').onclick=e=>{if(e.target.dataset.nav){page=e.target.dataset.nav;render()}};
function cards(a){return '<div class="grid">'+a.map(([t,h,p])=>`<article class="card"><span class="tag">${t}</span><h3>${h}</h3><p>${p}</p></article>`).join('')+'</div>'}
function render(){document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===page));let html='';
if(page==='Home')html=cards([['CAPTURE',`${data.notes.length} saved notes`,'Say “remember that” followed by your note. Your next search can retrieve it.'],['DELIVERY',`${data.tasks.filter(t=>t.status!=='DONE').length} open tasks`,'Say “add task” followed by the work. Track ownership, blockers and completion.'],['GOVERNANCE','Evidence before action','Use fictional supplier data to prepare an evidence request and review checklist.']])+`<h2>Your knowledge constellation</h2><div class="galaxy">${data.notes.length?data.notes.map((n,i)=>`<button class="star" data-note="${i}" style="left:${8+(i*31)%76}%;top:${15+(i*23)%65}%"><span>${escapeHTML(n.title.slice(0,28))}</span></button>`).join(''):'<p class="muted" style="padding:30px">Your first saved note becomes your first star. This is a 2D constellation; the 3D galaxy is pending.</p>'}</div>`;
if(page==='Notes')html=`<h2>Notes & memory</h2><input id="search" placeholder="Search your notes"><textarea id="noteText" placeholder="Write a note, then save it"></textarea><button id="addNote">Save note</button><div id="notesList"></div>`;
if(page==='GRC / TPRM')html=`<h2>Supplier review desk</h2><p class="muted">Preparation workflow. Checks require source documents and human decisions. No automatic compliance verdict.</p><input id="supplier" placeholder="Supplier name (fictional for testing)"><select id="tier"><option>Standard</option><option>High: sensitive data or critical service</option></select><textarea id="context" placeholder="Service, data involved, access, hosting and proposed use"></textarea><button id="review">Create evidence checklist</button><div id="reviewResult"></div>`;
if(page==='Work queue')html=`<h2>Work queue</h2><div class="row"><input id="taskText" placeholder="Task and intended outcome"><button id="addTask">Add task</button></div>`+data.tasks.map((t,i)=>`<div class="card row"><strong style="flex:1">${escapeHTML(t.text)}</strong><select data-task="${i}">${['NEXT','IN PROGRESS','WAITING','BLOCKED','DONE'].map(s=>`<option ${s===t.status?'selected':''}>${s}</option>`).join('')}</select><input data-blocker="${i}" placeholder="Blocker / evidence of completion" value="${escapeHTML(t.evidence||'')}"></div>`).join('');
if(['Email','LinkedIn'].includes(page))html=`<h2>${page} drafting desk</h2><div class="notice">Not connected. Nothing here reads your account, sends email or publishes posts.</div><textarea id="draftText" placeholder="Write or paste your draft. Avoid confidential information."></textarea><button id="draftSave">Save draft</button><button id="copyDraft">Copy draft</button><h3>Saved drafts</h3>`+data.drafts.filter(d=>d.channel===page).map(d=>`<article class="card"><span class="tag">DRAFT • NOT SENT</span><p class="note">${escapeHTML(d.text)}</p></article>`).join('');
if(page==='REA')html=`<h2>Website investigation</h2><div class="notice">REA 6.5.0 was tested in the engineering environment. This hosted dashboard has no local REA bridge.</div><input id="siteURL" placeholder="https://example.com"><textarea id="question" placeholder="What feature should the investigation explain?"></textarea><button id="requestREA">Queue investigation request</button><p class="muted">A queued request is not a completed teardown. Clean browser capture, evidence report and native voice routing remain pending.</p>`;
if(page==='Preflight')html=`<h2>Honest preflight</h2><button id="check">Run browser checks</button><pre id="checks" class="log">Run to check this browser.</pre><h3>Twelve-prompt delivery map</h3>`+['01 Notes and source retrieval: working locally; cloud brain not connected','02 Voice: browser dependent, needs your click and microphone permission','03 Source highlighting: notes shown; 3D camera pending','04 Character: Faithful greeting; deterministic commands, no autonomous executor','05 Recall: browser persistence and immediate retrieval','06 Preflight: browser checks only; no live API checks','07 REA: verified remotely, dashboard bridge pending','08 Clean investigation browser: pending','09 Evidence capture and fingerprints: pending','10 Teardown note creation: pending','11 Voice instructions and panel: basic commands working; teardown execution pending','12 Full teardown drill: pending'].map(x=>`<p class="muted">${x}</p>`).join('');
if(page==='Audit')html=`<h2>Action receipts</h2><p class="muted">Local records of dashboard actions. Export a backup for retention.</p><div class="log">${data.audit.map(a=>`${escapeHTML(a.at)} · ${escapeHTML(a.action)}`).join('<br>')||'No actions recorded yet.'}</div>`;
$('view').innerHTML=html;bind();}
function addNote(text){if(!text.trim())return;const n={title:text.trim().split(/\s+/).slice(0,7).join(' '),text:text.trim(),at:new Date().toISOString()};data.notes.push(n);log('Note saved: '+n.title);render();answer('Saved, Faithful. Your note is searchable now.');}
function addTask(text){if(!text.trim())return;data.tasks.push({text:text.trim(),status:'NEXT',evidence:''});log('Task created: '+text);render();answer('Added to your work queue, Faithful. It is marked NEXT, not completed.');}
function bind(){if($('addNote')){$('addNote').onclick=()=>addNote($('noteText').value);$('search').oninput=showNotes;showNotes()}if($('addTask'))$('addTask').onclick=()=>addTask($('taskText').value);document.querySelectorAll('[data-task]').forEach(e=>e.onchange=()=>{let t=data.tasks[+e.dataset.task];if(e.value==='DONE'&&!t.evidence.trim()){answer('Add completion evidence before marking this done.');e.value=t.status;return}t.status=e.value;log('Task status: '+t.text+' → '+t.status)});document.querySelectorAll('[data-blocker]').forEach(e=>e.onchange=()=>{data.tasks[+e.dataset.blocker].evidence=e.value;save()});document.querySelectorAll('[data-note]').forEach(e=>e.onclick=()=>answer(data.notes[+e.dataset.note].text));
if($('review'))$('review').onclick=()=>{let name=$('supplier').value.trim();if(!name)return answer('Enter a supplier name first.');let steps=['Service scope, business owner and criticality','Data inventory, lawful processing instructions and retention','Hosting locations, subprocessors and access controls','Security assurance with scope, issuer and expiry dates','Incident notification, recovery and service continuity','Contract, data processing terms and exit arrangements','Evidence gaps, risk owner and documented human approval'];let content=`Supplier: ${name}\nTier: ${$('tier').value}\nContext: ${$('context').value}\n\nEvidence required:\n`+steps.map((s,i)=>`${i+1}. ${s}`).join('\n')+'\n\nDecision: WAITING FOR EVIDENCE. No risk clearance issued.';data.notes.push({title:'Supplier review: '+name,text:content,at:new Date().toISOString()});log('Evidence checklist created for '+name);$('reviewResult').innerHTML='<pre class="log card">'+escapeHTML(content)+'</pre>';answer('The evidence checklist is saved, Faithful. The review is waiting for evidence and a human decision.');};
if($('draftSave')){$('draftSave').onclick=()=>{if(!$('draftText').value.trim())return;data.drafts.push({channel:page,text:$('draftText').value});log(page+' draft saved; not sent');render();answer('Draft saved. Nothing has been sent or published.');};$('copyDraft').onclick=async()=>{try{await navigator.clipboard.writeText($('draftText').value);answer('Copied to your clipboard.')}catch(e){answer('Clipboard access unavailable. Select the draft and copy it manually.')}}}
if($('requestREA'))$('requestREA').onclick=()=>{try{let u=new URL($('siteURL').value);if(!['https:','http:'].includes(u.protocol))throw Error();addTask('REA investigation requested: '+u.href+' | '+$('question').value)}catch(e){answer('Enter a full http or https website address.')}};
if($('check'))$('check').onclick=()=>{let checks=[['Page and command interface',!!$('instruction')],['Browser storage',storageOK],['Speech synthesis','speechSynthesis'in window],['Speech recognition','SpeechRecognition'in window||'webkitSpeechRecognition'in window],['Mute mode',new URLSearchParams(location.search).get('mute')==='1']];$('checks').textContent=checks.map(([n,v])=>(v?'PASS':'WARN')+' '+n).join('\n')+'\nNOT CONNECTED: AI API, Gmail, LinkedIn, local REA bridge.\nFull twelve-prompt preflight: INCOMPLETE.';};}
function showNotes(){let q=$('search').value.toLowerCase();$('notesList').innerHTML=data.notes.filter(n=>(n.title+' '+n.text).toLowerCase().includes(q)).map(n=>`<article class="card" style="margin-top:12px"><h3>${escapeHTML(n.title)}</h3><p class="note">${escapeHTML(n.text)}</p></article>`).join('')||'<p class="muted">No matching notes.</p>'}
async function command(text){text=text.trim();if(!text)return;let lower=text.toLowerCase();if(/^(stop|wait)[.!]?$/.test(lower)){clearTimeout(timer);buffer='';if(recognition)recognition.abort();if('speechSynthesis'in window)speechSynthesis.cancel();$('status').textContent='Stopped';return}if(lower.startsWith('remember that '))return addNote(text.slice(14));if(lower.startsWith('add task '))return addTask(text.slice(9));if(/^(hello|hi|good morning)[!. ]*$/.test(lower))return answer('Hello, Faithful. Ready when you are.');let route=sections.find(n=>lower==='open '+n.toLowerCase());if(route){page=route;render();return answer('Opened '+route+'.')}if(lower.startsWith('review supplier ')){page='GRC / TPRM';render();$('supplier').value=text.slice(16);return answer('Supplier review opened. Add the service context, then create the evidence checklist.')}let words=lower.split(/\W+/).filter(w=>w.length>3);let found=data.notes.map(n=>({n,score:words.reduce((a,w)=>a+(n.title.toLowerCase().includes(w)?3:0)+(n.text.toLowerCase().includes(w)?1:0),0)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score).slice(0,3);if(brainReady){$('status').textContent='Thinking locally';try{let r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:text,notes:found.map(x=>x.n)})});let v=await r.json();if(!r.ok)throw new Error(v.error||'Local AI unavailable');answer(v.answer);return}catch(e){answer(e.message);return}}if(found.length)answer('From your saved notes (keyword matches, not an AI-generated answer):\n\n'+found.map(x=>x.n.title+': '+x.n.text).join('\n\n'));else answer('I do not have a connected AI brain or a matching saved note yet, Faithful. I can save notes, add tasks, open a desk and prepare supplier checklists. Try “remember that”, “add task”, or “review supplier”.');}
$('send').onclick=()=>{let t=$('instruction').value;$('instruction').value='';command(t)};$('instruction').onkeydown=e=>{if(e.key==='Enter')$('send').click()};$('stop').onclick=()=>command('stop');$('voice').onclick=()=>{voice=!voice;$('voice').textContent=voice?'Voice on':'Enable voice';if(voice)answer('Hello, Faithful. I am ready for your instruction.');else if('speechSynthesis'in window)speechSynthesis.cancel()};
$('mic').onclick=()=>{let R=window.SpeechRecognition||window.webkitSpeechRecognition;if(!R)return answer('Voice recognition is unavailable in this browser. Type below, or try Chrome or Edge.');if(recognition){recognition.abort();recognition=null;return}recognition=new R();recognition.lang='en-GB';recognition.continuous=true;recognition.interimResults=false;recognition.onresult=e=>{for(let i=e.resultIndex;i<e.results.length;i++){let t=e.results[i][0].transcript.trim();if(/^(stop|wait)[.!]?$/.test(t.toLowerCase()))return command(t);buffer+=(buffer?' ':'')+t;clearTimeout(timer);timer=setTimeout(()=>{let t=buffer;buffer='';$('instruction').value=t;command(t)},FINISH_MS)}};recognition.onerror=e=>{answer('Microphone: '+e.error+'. You can still type your instruction.');};recognition.onend=()=>{recognition=null;$('status').textContent='Ready'};recognition.start();$('status').textContent='Listening'};
$('export').onclick=()=>{let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='palm92-jarvis-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('import').onchange=async e=>{try{let v=JSON.parse(await e.target.files[0].text());if(!['notes','tasks','audit','drafts'].every(k=>Array.isArray(v[k])))throw Error();if(!confirm('Replace current browser data with this backup? Export first if needed.'))return;data=v;save();render();answer('Backup imported.')}catch(e){answer('That backup could not be imported. Current data was preserved.')}};save();render();

let brainReady=false;
async function checkBrain(){if(!['localhost','127.0.0.1'].includes(location.hostname)){$('brainState').textContent='Hosted mode: local AI requires the Windows package';return}try{let r=await fetch('/api/brain');let v=await r.json();brainReady=!!v.ready;$('brainState').textContent=brainReady?'Local Ollama connected: '+v.models.join(', '):v.problem}catch(e){$('brainState').textContent='Local AI bridge unavailable'}}
function voices(){if(!('speechSynthesis'in window))return;let selected=$('voiceChoice').value;$('voiceChoice').innerHTML='<option value="">Automatic voice</option>'+speechSynthesis.getVoices().filter(v=>v.lang.startsWith('en')).map(v=>'<option value="'+escapeHTML(v.name)+'">'+escapeHTML(v.name)+'</option>').join('');$('voiceChoice').value=selected}
$('speed').oninput=()=>{$('speedValue').textContent=$('speed').value+'×';try{localStorage.setItem('palm92-speed',$('speed').value)}catch(e){}};try{$('speed').value=localStorage.getItem('palm92-speed')||'1.2';$('speedValue').textContent=$('speed').value+'×'}catch(e){}
if('speechSynthesis'in window){speechSynthesis.onvoiceschanged=voices;voices()}checkBrain();
